type IssueTx = Parameters<Parameters<Db["transaction"]>[0]>[0];

/**
 * Raises a project's counter to the highest number any of its rows carries
 * and returns the result. The counter never goes back down, so a number stays
 * retired after its issue is archived, deleted or moved away.
 */
function raiseIssueNumberFloor(
  tx: IssueTx,
  orgId: OrgId,
  projectId: ProjectId,
): number {
  const highest = tx
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .get();
  const counter = tx
    .select({ lastNumber: issueNumberCounters.lastNumber })
    .from(issueNumberCounters)
    .where(eq(issueNumberCounters.projectId, projectId))
    .get();

  const floor = Math.max(counter?.lastNumber ?? 0, highest?.value ?? 0);
  tx.insert(issueNumberCounters)
    .values({ orgId, projectId, lastNumber: floor })
    .onConflictDoUpdate({
      target: issueNumberCounters.projectId,
      set: { lastNumber: floor },
    })
    .run();
  return floor;
}

/** Allocates the next number of a project inside an open transaction. */
function reserveIssueNumber(
  tx: IssueTx,
  orgId: OrgId,
  projectId: ProjectId,
): number {
  const next = raiseIssueNumberFloor(tx, orgId, projectId) + 1;
  tx.update(issueNumberCounters)
    .set({ lastNumber: next })
    .where(eq(issueNumberCounters.projectId, projectId))
    .run();
  return next;
}

/** Next per-project issue number. Archived issues keep their number. */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  return getDb().transaction((tx) => reserveIssueNumber(tx, orgId, projectId));
}

