/**
 * Moves an issue to another project of the same organization. The issue takes
 * that project's next number. The source counter is raised before the row
 * leaves, so the number it carried stays retired. Labels, comments and
 * attachments reference the issue id and are left alone.
 */
export async function transferIssueToProject(
  orgId: OrgId,
  issueId: IssueId,
  toProjectId: ProjectId,
): Promise<Issue> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb().transaction((tx) => {
    const current = tx
      .select()
      .from(issues)
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .get();
    if (!current) throw new Error(`Issue ${issueId} not found`);

    raiseIssueNumberFloor(tx, orgId, current.projectId as ProjectId);
    const number = reserveIssueNumber(tx, orgId, toProjectId);

    return tx
      .update(issues)
      .set({ projectId: toProjectId, number, updatedAt: stamp })
