/**
 * Moving an issue to another project of the same workspace: numbering, gates,
 * the one event it publishes, and the audit and search rows that follow it.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as activityService from "@/server/services/activity-service";
import * as issueService from "@/server/services/issue-service";
import * as searchService from "@/server/services/search-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { OrgId } from "@/types/common";
import type { Project } from "@/types/project";
import type { TaskflowEventMap, Unsubscribe } from "@/types/event";

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detachers.push(activityService.registerActivityListeners());
  detachers.push(searchService.registerSearchListeners());
});

afterEach(() => {
  while (detachers.length > 1) detachers.pop()?.();
});

afterAll(() => {
  while (detachers.length > 0) detachers.pop()?.();
  cleanup();
});

/** A tenant with its own source project plus a second project to move into. */
async function setup(slug: string, plan: "growth" | "free" = "growth") {
  const tenant: Tenant = await createTenant(slug, plan);
  const ops: Project = await projectRepo.insertProject({
    orgId: tenant.org.id,
    name: "Operations",
    slug: "operations",
    key: "OPS",
    description: null,
    visibility: "org",
    leadId: null,
    color: "#6366f1",
    targetDate: null,
  });
  return { tenant, ops };
}

function capture<K extends "issue.moved">(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  const off = subscribe(type, (payload) => {
    seen.push(payload);
  });
  detachers.push(off);
  return seen;
}

describe("services/issue-service moveIssueToProject", () => {
  it("re-files the issue under the target with the target's next number", async () => {
    const { tenant, ops } = await setup("movefields");
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Filed in the wrong project" }),
    );
    const inOps = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, ops.id, { title: "Already in ops" }),
    );
    expect(inOps.number).toBe(1);

    const moved = await issueService.moveIssueToProject(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      toProjectId: ops.id,
    });

    expect(moved).toMatchObject({
      id: issue.id,
      projectId: ops.id,
      number: 2,
      title: "Filed in the wrong project",
      status: "backlog",
      priority: "none",
    });
  });

  it("retires the number the issue left behind, even when it was the highest", async () => {
    const { tenant, ops } = await setup("moveretire");
    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Stays put" }),
    );
    const highest = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Leaves" }),
    );
    expect(highest.number).toBe(2);

    await issueService.moveIssueToProject(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: highest.id,
      toProjectId: ops.id,
    });

    const next = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Continues after 2" }),
    );
    expect(next.number).toBe(3);
    await expect(
      issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id),
    ).resolves.toBe(4);
  });

  it("changes nothing and publishes nothing for a move within the same project", async () => {
    const { tenant } = await setup("movesame");
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Already here" }),
    );
    const seen = capture("issue.moved");

    const result = await issueService.moveIssueToProject(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      toProjectId: tenant.project.id,
    });

    expect(result).toEqual(issue);
    expect(seen).toHaveLength(0);
  });

  it("refuses a viewer and leaves the issue where it was", async () => {
    const { tenant, ops } = await setup("moveviewer");
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Not yours to move" }),
    );

    await expect(
      issueService.moveIssueToProject(tenant.actors.viewer, {
        orgId: tenant.org.id,
        issueId: issue.id,
        toProjectId: ops.id,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    const stored = await issueRepo.findIssueById(tenant.org.id, issue.id);
    expect(stored).toMatchObject({ projectId: tenant.project.id, number: 1 });
  });

  it("refuses a move into a project at its plan issue quota", async () => {
    const { tenant, ops } = await setup("movequota", "free");
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "One too many" }),
    );
    for (let number = 1; number <= 100; number += 1) {
      await issueRepo.insertIssue(
        issueInput(tenant.org.id, ops.id, { title: `Seed ${number}` }),
        tenant.actors.member.userId,
        number,
      );
    }
    const seen = capture("issue.moved");

    await expect(
      issueService.moveIssueToProject(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        toProjectId: ops.id,
      }),
    ).rejects.toThrow(/allows no more issues/);

    expect(seen).toHaveLength(0);
    const stored = await issueRepo.findIssueById(tenant.org.id, issue.id);
    expect(stored).toMatchObject({ projectId: tenant.project.id, number: 1 });
  });

  it("publishes one issue.moved carrying both projects and both numbers", async () => {
    const { tenant, ops } = await setup("movepublish");
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Announce me" }),
    );
    const seen = capture("issue.moved");

    await issueService.moveIssueToProject(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      toProjectId: ops.id,
    });

    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.member,
      issueId: issue.id,
      fromProjectId: tenant.project.id,
      toProjectId: ops.id,
      fromNumber: 1,
      toNumber: 1,
    });
  });

  it("records the move in the audit log under the target project", async () => {
    const { tenant, ops } = await setup("moveaudit");
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Audit me" }),
    );

    await issueService.moveIssueToProject(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      toProjectId: ops.id,
    });

    const page = await activityService.listActivity(tenant.actors.owner, {
      orgId: tenant.org.id,
      projectId: ops.id,
      action: ["issue.moved"],
      limit: 50,
      cursor: null,
    });
    expect(page.items).toHaveLength(1);
    expect(page.items[0]).toMatchObject({
      action: "issue.moved",
      actorId: tenant.userIds.member,
      subjectKind: "issue",
      subjectId: issue.id,
      projectId: ops.id,
      metadata: {
        fromProjectId: tenant.project.id,
        toProjectId: ops.id,
        fromNumber: 1,
        toNumber: 1,
      },
    });
  });

  it("moves the search document with the issue", async () => {
    const { tenant, ops } = await setup("movesearch");
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Findable relocation" }),
    );

    await issueService.moveIssueToProject(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      toProjectId: ops.id,
    });

    const query = (projectId: Project["id"]) =>
      searchService.search(tenant.actors.member, {
        orgId: tenant.org.id as OrgId,
        q: "Findable",
        kinds: ["issue"],
        projectId,
        limit: 25,
        cursor: null,
      });

    await expect(query(ops.id)).resolves.toMatchObject({ total: 1 });
    await expect(query(tenant.project.id)).resolves.toMatchObject({ total: 0 });
  });
});

